// Supabase sync helper — writes data to Supabase in parallel with Prisma
// Uses respondent `code` as the key (not Prisma CUID id)
// Supabase tables use uuid PKs generated by Supabase itself
import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

if (!supabaseUrl || !supabaseKey) {
  console.error('[Supabase] Missing NEXT_PUBLIC_SUPABASE_URL or NEXT_PUBLIC_SUPABASE_ANON_KEY')
}

export const supabase = (supabaseUrl && supabaseKey)
  ? createClient(supabaseUrl, supabaseKey, {
      auth: { persistSession: false }
    })
  : null

// ─── Helper: get respondent UUID from Supabase by code ───────────────
async function getSupabaseRespondentId(code: string): Promise<string | null> {
  if (!supabase) return null
  const { data, error } = await supabase
    .from('respondents')
    .select('id')
    .eq('code', code)
    .maybeSingle()
  if (error) {
    console.error('[Supabase] Error fetching respondent ID:', error.message)
    return null
  }
  return data?.id ?? null
}

// ─── Respondent sync (upsert by code, let Supabase generate UUID) ────
export async function syncRespondent(data: {
  code: string
  school: string | null
  status: string
  current_stage: string
  stage_index: number
  high_risk: boolean
  consent_given: boolean
  started_at: string
  completed_at: string | null
}) {
  if (!supabase) { console.warn('[Supabase] Client null — skipping sync'); return }
  console.log('[Supabase] Syncing respondent:', data.code)
  const { error } = await supabase
    .from('respondents')
    .upsert({
      code: data.code,
      school: data.school,
      status: data.status,
      current_stage: data.current_stage,
      stage_index: data.stage_index,
      high_risk: data.high_risk,
      consent_given: data.consent_given,
      started_at: data.started_at,
      completed_at: data.completed_at,
    }, { onConflict: 'code' })
  if (error) console.error('[Supabase] Error syncing respondent:', error.message, error.details)
  else console.log('[Supabase] Respondent synced OK:', data.code)
}

// ─── Demographics sync ───────────────────────────────────────────────
export async function syncDemographics(respondentCode: string, data: Record<string, unknown>) {
  if (!supabase) return
  const respondentId = await getSupabaseRespondentId(respondentCode)
  if (!respondentId) { console.error('[Supabase] Cannot sync demographics — respondent not found:', respondentCode); return }
  console.log('[Supabase] Syncing demographics for:', respondentCode, 'uuid:', respondentId)
  const { error } = await supabase
    .from('demographics')
    .upsert({
      respondent_id: respondentId,
      data: data,  // jsonb
    }, { onConflict: 'respondent_id' })
  if (error) console.error('[Supabase] Error syncing demographics:', error.message, error.details)
  else console.log('[Supabase] Demographics synced OK')
}

