// ─── Audit log sync ──────────────────────────────────────────────────
export async function syncAuditLog(respondentCode: string | null, action: string, detail?: string) {
  if (!supabase || !respondentCode) return
  const respondentId = await getSupabaseRespondentId(respondentCode)
  // audit_logs.respondent_id is nullable, so we can insert even without UUID
  const { error } = await supabase
    .from('audit_logs')
    .insert({
      respondent_id: respondentId,
      action,
      detail: detail ?? null,
    })
  if (error) console.error('[Supabase] Error syncing audit log:', error.message)
}

// ─── Research code sync ──────────────────────────────────────────────
export async function syncResearchCode(code: string, school?: string | null, classGrade?: string | null) {
  if (!supabase) return
  const { error } = await supabase
    .from('research_codes')
    .upsert({
      code,
      school: school ?? null,
      class_grade: classGrade ?? null,
    }, { onConflict: 'code' })
  if (error) console.error('[Supabase] Error syncing research code:', error.message)
}

// ─── Update research code used status ────────────────────────────────
export async function syncResearchCodeUsed(code: string, used: boolean) {
  if (!supabase) return
  const { error } = await supabase
    .from('research_codes')
    .update({ used })
    .eq('code', code)
  if (error) console.error('[Supabase] Error updating code used:', error.message)
}
